INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-18-eu-en16931-2026-standard', '2026-03-18', '2026-03', 'The European standards body CEN has formally released EN 16931-1:2026, the updated semantic standard underpinning ViDA''s Digital Reporting Requirements — notably confirming that member states can use alternative standards for domestic e-invoicing mandates without conflicting with the EU-wide cross-border framework.', '<h3>🇪🇺 CEN releases updated EN 16931-1:2026 standard, giving member states flexibility on domestic formats</h3>
<p>CEN, the European standards body, has formally released EN 16931-1:2026 — an updated version of the semantic data standard that underpins electronic invoicing across the EU, specifically adapted to support ViDA''s Digital Reporting Requirements for cross-border B2B transactions. This supersedes the previous version of the standard and adds new fields needed to support digital reporting, rather than just structured invoice exchange on its own.</p>
<p>One clarification in this update genuinely matters for how the countries in this tracker relate to each other: member states retain flexibility to use alternative standards for their own domestic e-invoicing mandates, without that choice conflicting with the EU-wide cross-border framework. This is why, for example, Italy''s FatturaPA and Poland''s KSeF formats can continue operating as genuinely national systems rather than needing to be replaced by EN 16931 wholesale — the EU-wide standard governs cross-border reporting specifically, while domestic systems retain their own established formats underneath.</p>
<p><strong>What this means for your team:</strong> if your business operates across multiple EU member states, don''t assume EN 16931-1:2026 replaces whatever domestic format a given country already requires — the two operate at different levels, cross-border versus domestic. The practical planning question is whether your systems can produce both: your existing domestic format for that country''s local requirements, and genuine EN 16931-1:2026-compliant data for cross-border transactions once the 2030 Digital Reporting Requirements take effect.</p>', 'https://taxation-customs.ec.europa.eu/news/vat-digital-age-2026-work-programme-available-2026-05-22_en', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-18-eu-en16931-2026-standard', id FROM countries WHERE name_en = 'European Union';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-18-eu-en16931-2026-standard', 'en', 'CEN releases updated EN 16931-1:2026 standard, giving member states flexibility on domestic formats', 'The European standards body CEN has formally released EN 16931-1:2026, the updated semantic standard underpinning ViDA''s Digital Reporting Requirements — notably confirming that member states can use alternative standards for domestic e-invoicing mandates without conflicting with the EU-wide cross-border framework.', '<h3>🇪🇺 CEN releases updated EN 16931-1:2026 standard, giving member states flexibility on domestic formats</h3>
<p>CEN, the European standards body, has formally released EN 16931-1:2026 — an updated version of the semantic data standard that underpins electronic invoicing across the EU, specifically adapted to support ViDA''s Digital Reporting Requirements for cross-border B2B transactions. This supersedes the previous version of the standard and adds new fields needed to support digital reporting, rather than just structured invoice exchange on its own.</p>
<p>One clarification in this update genuinely matters for how the countries in this tracker relate to each other: member states retain flexibility to use alternative standards for their own domestic e-invoicing mandates, without that choice conflicting with the EU-wide cross-border framework. This is why, for example, Italy''s FatturaPA and Poland''s KSeF formats can continue operating as genuinely national systems rather than needing to be replaced by EN 16931 wholesale — the EU-wide standard governs cross-border reporting specifically, while domestic systems retain their own established formats underneath.</p>
<p><strong>What this means for your team:</strong> if your business operates across multiple EU member states, don''t assume EN 16931-1:2026 replaces whatever domestic format a given country already requires — the two operate at different levels, cross-border versus domestic. The practical planning question is whether your systems can produce both: your existing domestic format for that country''s local requirements, and genuine EN 16931-1:2026-compliant data for cross-border transactions once the 2030 Digital Reporting Requirements take effect.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-22-eu-vida-2026-work-programme', '2026-05-22', '2026-05', 'The European Commission has published its 2026 Work Programme for VAT in the Digital Age, setting out the complete phased timeline from January 2027 through the final 2035 milestone, when domestic real-time reporting systems must align with the cross-border framework.', '<h3>🇪🇺 European Commission publishes the full ViDA implementation roadmap through 2035</h3>
<p>Building on the implementation strategy released in September 2025, the European Commission has now published its 2026 Work Programme, setting out concrete phased dates for the VAT in the Digital Age package first formally adopted in March 2025. Worth having the full sequence in view rather than just the most commonly cited 2030 date: from 1 January 2027, the One-Stop Shop scheme extends to cover B2C supplies in the e-charging sector, alongside various legislative clarifications for OSS/IOSS users. From 1 July 2028, platforms in short-term accommodation rental and passenger transport must comply with new deemed-supplier VAT rules, and the main Single VAT Registration reforms — including mandatory reverse charge for non-established suppliers — begin.</p>
<p>The most significant and widely-discussed date remains 1 July 2030: cross-border B2B transactions become subject to genuine Digital Reporting Requirements based on mandatory e-invoicing, with e-invoicing becoming the default method across the EU. But the package doesn''t end there — by 1 January 2035, member states that already run their own domestic real-time transaction reporting systems must align those systems with the EU-wide cross-border digital reporting framework, the final phase of the whole package.</p>
<p><strong>What this means for your team:</strong> if your planning has focused solely on the 2030 cross-border deadline, this roadmap is worth a closer look — the platform economy and Single VAT Registration changes from 2028 arrive first, and apply specifically to short-term rental and passenger transport platforms regardless of when you address cross-border invoicing itself. Businesses in EU countries that already run their own domestic clearance or reporting systems, such as Italy or Poland, should also treat 2035 as a real, if distant, planning marker — domestic systems built today will eventually need to interoperate with the EU-wide framework, not simply continue running in parallel indefinitely.</p>', 'https://taxation-customs.ec.europa.eu/news/vat-digital-age-2026-work-programme-available-2026-05-22_en', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-22-eu-vida-2026-work-programme', id FROM countries WHERE name_en = 'European Union';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-22-eu-vida-2026-work-programme', 'en', 'European Commission publishes the full ViDA implementation roadmap through 2035', 'The European Commission has published its 2026 Work Programme for VAT in the Digital Age, setting out the complete phased timeline from January 2027 through the final 2035 milestone, when domestic real-time reporting systems must align with the cross-border framework.', '<h3>🇪🇺 European Commission publishes the full ViDA implementation roadmap through 2035</h3>
<p>Building on the implementation strategy released in September 2025, the European Commission has now published its 2026 Work Programme, setting out concrete phased dates for the VAT in the Digital Age package first formally adopted in March 2025. Worth having the full sequence in view rather than just the most commonly cited 2030 date: from 1 January 2027, the One-Stop Shop scheme extends to cover B2C supplies in the e-charging sector, alongside various legislative clarifications for OSS/IOSS users. From 1 July 2028, platforms in short-term accommodation rental and passenger transport must comply with new deemed-supplier VAT rules, and the main Single VAT Registration reforms — including mandatory reverse charge for non-established suppliers — begin.</p>
<p>The most significant and widely-discussed date remains 1 July 2030: cross-border B2B transactions become subject to genuine Digital Reporting Requirements based on mandatory e-invoicing, with e-invoicing becoming the default method across the EU. But the package doesn''t end there — by 1 January 2035, member states that already run their own domestic real-time transaction reporting systems must align those systems with the EU-wide cross-border digital reporting framework, the final phase of the whole package.</p>
<p><strong>What this means for your team:</strong> if your planning has focused solely on the 2030 cross-border deadline, this roadmap is worth a closer look — the platform economy and Single VAT Registration changes from 2028 arrive first, and apply specifically to short-term rental and passenger transport platforms regardless of when you address cross-border invoicing itself. Businesses in EU countries that already run their own domestic clearance or reporting systems, such as Italy or Poland, should also treat 2035 as a real, if distant, planning marker — domestic systems built today will eventually need to interoperate with the EU-wide framework, not simply continue running in parallel indefinitely.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-17-eu-vida-open-implementation-questions', '2026-04-17', '2026-04', 'The EU''s Group on the Future of VAT has confirmed that core definitional questions for ViDA''s Digital Reporting Requirements — including what counts as invoice ''issuance'', ''transmission'', and genuine ''real-time'' reporting — remain open, with final Explanatory Notes not expected until late 2026 or early 2027.', '<h3>🇪🇺 What ''real-time'' actually means under ViDA is still being defined</h3>
<p>The technically demanding heart of ViDA — near-real-time Digital Reporting Requirements for cross-border B2B transactions — is still working through genuinely foundational definitional questions, according to the EU''s own Group on the Future of VAT, which addressed the topic directly at its most recent meeting. Draft Explanatory Notes are in progress through spring 2026, but final versions aren''t expected until the end of 2026 or early 2027 — meaningfully later than the underlying 1 July 2030 deadline might suggest is urgent right now, though the gap is set to close as that date approaches.</p>
<p>The open questions are genuinely substantive, not just administrative housekeeping: work is still required to define exactly what "issuance" and "transmission" of an e-invoice mean in this context, how the acceptance process should function, and — perhaps most fundamentally — what actually constitutes a "real-time" reporting system in the first place. These aren''t small implementation footnotes; they''re the actual operating definitions that will determine what compliant systems are required to do.</p>
<p><strong>What this means for your team:</strong> with the 2030 deadline still several years out and core definitions still being worked through at the EU level, this isn''t yet the moment to lock in a specific technical build based on assumptions about what "real-time" will mean. It is, however, worth tracking the Explanatory Notes'' progress toward their expected late-2026/early-2027 finalisation, since that''s realistically the point at which planning can move from general direction to specific technical requirements.</p>', 'https://taxation-customs.ec.europa.eu/news/vat-digital-age-2026-work-programme-available-2026-05-22_en', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-04-17-eu-vida-open-implementation-questions', id FROM countries WHERE name_en = 'European Union';
